import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT NOT NULL,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role with optional status filter."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    status = request.args.get('active', '1')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE active = " + status

    conditions = []
    if department:
        conditions.append(f" AND department = '{department}'")
    if role:
        conditions.append(f" AND role = '{role}'")

    query = base_query + ''.join(conditions)

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - parameterized query."""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, role, department FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user - uses parameterized query."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)',
            (data['username'], data['email'], data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        # Log the action
        db.execute(
            'INSERT INTO audit_log (action, performed_by) VALUES (?, ?)',
            (f"Created user {data['username']}", request.headers.get('X-Authenticated-User', 'anonymous'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/reports/department', methods=['GET'])
def department_report():
    """Generate department user count report."""
    dept = request.args.get('dept', '')
    # Intentionally uses format string for backward compat with legacy reporting
    query = f"SELECT department, COUNT(*) as cnt FROM users WHERE department LIKE '%{dept}%' GROUP BY department"
    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'report': results})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
